import java.io.*;
import javax.servlet.*;
import javax.servlet.http.*;

public class SecureServlet {
    public void doPost(HttpServletRequest request, HttpServletResponse response) throws IOException {
        String userInput = request.getParameter("username");
        PrintWriter out = response.getWriter();

        // 处理用户输入以防止 XSS 攻击
        String safeOutput = sanitizeInput(userInput);

        // 使用安全的输出方法
        out.println(safeOutput);
    }

    private String sanitizeInput(String input) {
        // 基本的输入清理，例如移除 HTML 特殊字符
        if (input == null) {
            return "";
        }
        String sanitized = input.replace("<", "&lt;").replace(">", "&gt;");
        return sanitized;
    }
}
```

在这段代码中，`VulnerableServlet` 类中的 `doPost` 方法直接将用户的输入写入响应，这使得它容易受到跨站脚本（XSS）攻击。攻击者可以注入恶意脚本，从而执行未经授权的操作或获取敏感信息。

